read n
queue of pairs q
push(q,pair(1,n))

while(q is not empty){

    pair current = front(q)

    mid = (current.first + current.second) / 2
    print mid

    if(mid > current.first)
         push(q,pair(current.first, mid - 1))

    if(mid < current.second)
         push(q,pair(mid + 1, current.second))

    pop_front(q)
}

